:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --card-back: #3d3d5c;
  --card-front: #f0f0f5;
  --accent: #ffb347;
  --text: #f5f5fa;
  --text-muted: #b0b0c0;
  --matched: #4caf50;
  --radius: 12px;
  --gap: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 0%, #2e2e4a, var(--bg));
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 24px 16px;
}

.game {
  width: 100%;
  max-width: 560px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.game-header {
  text-align: center;
}

h1 {
  font-size: 1.8rem;
  letter-spacing: 0.02em;
  color: var(--accent);
}

.subtitle {
  margin-top: 6px;
  font-size: 1rem;
  color: var(--text-muted);
}

.status-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 16px;
  font-size: 1.1rem;
  min-height: 2rem;
}

.win-message {
  color: var(--matched);
  font-weight: 600;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
  width: 100%;
  perspective: 800px;
}

.card {
  aspect-ratio: 1 / 1;
  border: none;
  border-radius: var(--radius);
  background: var(--card-back);
  cursor: pointer;
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.35s ease, box-shadow 0.2s ease;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.35);
  font-size: 1rem;
  color: transparent;
  padding: 0;
}

.card::before {
  content: '';
  position: absolute;
  inset: 6px;
  border-radius: calc(var(--radius) - 4px);
  background: var(--card-back);
  border: 2px solid rgba(255, 255, 255, 0.08);
  transition: background 0.2s ease;
}

.card:hover:not(:disabled) {
  transform: translateY(-3px);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.45);
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.card:active:not(:disabled) {
  transform: scale(0.96);
}

.card.flipped,
.card.matched {
  transform: rotateY(180deg);
  cursor: default;
}

.card.flipped::before,
.card.matched::before {
  background: var(--card-front);
}

.card.matched {
  box-shadow: 0 0 0 3px var(--matched), 0 4px 10px rgba(0, 0, 0, 0.35);
}

.card.matched::before {
  background: var(--card-color);
  border-color: rgba(0, 0, 0, 0.15);
}

.card.flipped::before {
  background: var(--card-color);
  border-color: rgba(0, 0, 0, 0.15);
}

.card:disabled {
  cursor: default;
}

.btn {
  font: inherit;
  font-weight: 600;
  font-size: 1.1rem;
  padding: 12px 32px;
  border-radius: 999px;
  border: 2px solid var(--accent);
  background: var(--accent);
  color: #1e1e2f;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease;
  box-shadow: 0 4px 12px rgba(255, 179, 71, 0.3);
}

.btn:hover {
  background: #ffc266;
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(255, 179, 71, 0.4);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

.btn:active {
  transform: scale(0.97);
  box-shadow: 0 2px 8px rgba(255, 179, 71, 0.3);
}

@media (max-width: 480px) {
  body {
    padding: 16px 12px;
    font-size: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  :root {
    --gap: 8px;
  }
  .btn {
    padding: 10px 24px;
    font-size: 1rem;
  }
}

(function () {
  'use strict';

  const COLORS = [
    '#e63946', '#f4a261', '#2a9d8f', '#457b9d',
    '#9b5de5', '#f15bb5', '#00bbf9', '#00f5d4'
  ];

  const boardEl = document.getElementById('board');
  const movesEl = document.getElementById('moves');
  const winEl = document.getElementById('win-message');
  const newGameBtn = document.getElementById('new-game');

  let deck = [];
  let firstCard = null;
  let secondCard = null;
  let lock = false;
  let moves = 0;
  let matchedPairs = 0;

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function createDeck() {
    const cards = [];
    COLORS.forEach((color, idx) => {
      cards.push({ id: idx, color });
      cards.push({ id: idx, color });
    });
    return shuffle(cards);
  }

  function updateMoves() {
    movesEl.textContent = 'Moves: ' + moves;
  }

  function createCardElement(card, index) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'card';
    btn.dataset.id = card.id;
    btn.dataset.index = index;
    btn.style.setProperty('--card-color', card.color);
    btn.setAttribute('aria-label', 'Card ' + (index + 1) + ', face down');
    btn.setAttribute('aria-pressed', 'false');
    btn.addEventListener('click', onCardClick);
    return btn;
  }

  function renderBoard() {
    boardEl.innerHTML = '';
    deck.forEach((card, i) => {
      boardEl.appendChild(createCardElement(card, i));
    });
  }

  function onCardClick(event) {
    const card = event.currentTarget;
    if (lock) return;
    if (card.classList.contains('flipped') || card.classList.contains('matched')) return;

    flipCard(card);

    if (!firstCard) {
      firstCard = card;
      return;
    }

    secondCard = card;
    moves++;
    updateMoves();
    lock = true;

    if (firstCard.dataset.id === secondCard.dataset.id) {
      handleMatch();
    } else {
      handleMismatch();
    }
  }

  function flipCard(card) {
    card.classList.add('flipped');
    card.setAttribute('aria-pressed', 'true');
    const index = Number(card.dataset.index);
    card.setAttribute('aria-label', 'Card ' + (index + 1) + ', face up');
  }

  function handleMatch() {
    firstCard.classList.add('matched');
    secondCard.classList.add('matched');
    firstCard.disabled = true;
    secondCard.disabled = true;
    matchedPairs++;
    resetTurn();

    if (matchedPairs === COLORS.length) {
      winEl.textContent = 'You win! Completed in ' + moves + ' moves.';
    }
  }

  function handleMismatch() {
    setTimeout(() => {
      [firstCard, secondCard].forEach((card) => {
        if (!card) return;
        card.classList.remove('flipped');
        card.setAttribute('aria-pressed', 'false');
        const index = Number(card.dataset.index);
        card.setAttribute('aria-label', 'Card ' + (index + 1) + ', face down');
      });
      resetTurn();
    }, 800);
  }

  function resetTurn() {
    firstCard = null;
    secondCard = null;
    lock = false;
  }

  function startGame() {
    deck = createDeck();
    firstCard = null;
    secondCard = null;
    lock = false;
    moves = 0;
    matchedPairs = 0;
    updateMoves();
    winEl.textContent = '';
    renderBoard();
  }

  newGameBtn.addEventListener('click', startGame);

  startGame();
})();
